typedef struct {
    int id;
    int remaining_time;
} Job;

// Centralized management ensures simple policy adaptation (FCFS, SJF)
Queue single_job_queue;
Mutex queue_lock;

Job* get_next_job() {
    Lock_Acquire(queue_lock);
    if (Queue_Empty(single_job_queue)) {
        Lock_Release(queue_lock);
        return NULL;
    }
    // Policy applied: e.g., FCFS (dequeue front)
    Job* job = Queue_Dequeue(single_job_queue);
    Lock_Release(queue_lock);
    return job;
}

// All N CPUs call this central function to pull work
void cpu_worker_loop() {
    Job* work = get_next_job();
    if (work) { Execute(work); }
}
